import json
with open('entry.jsonl') as f:
    lines = f.readlines()
for i,l in enumerate(lines):
    o = json.loads(l)
    if o.get('type')!='message': 
        continue
    m = o['message']
    role = m.get('role')
    content = m.get('content')
    # summarize content
    parts=[]
    if isinstance(content,str):
        parts.append(('text',content[:80]))
    elif isinstance(content,list):
        for c in content:
            t = c.get('type')
            if t=='text':
                parts.append(('text',c['text'][:80]))
            elif t=='tool_use':
                parts.append(('tool_use:'+c.get('name',''), json.dumps(c.get('input',{}))[:80]))
            elif t=='tool_result':
                tc = c.get('content')
                s = json.dumps(tc)[:80] if not isinstance(tc,str) else tc[:80]
                parts.append(('tool_result', s))
            elif t=='thinking':
                parts.append(('thinking',c.get('thinking','')[:80]))
            else:
                parts.append((t,''))
    print(i, role, '|', parts[:3] if parts else '')
" 2>&1 | head -120', 'description': 'Summarize each message'}

